-- Rewrites the search-and-rescue payload project with general text and many figures (its old outcomes
-- listed numbers the paper does not support), updates the profile title and bio, and removes a junk
-- experience entry. Figures live in the portfolio-media bucket under projects/offline-ai-payload/.
update public.profiles set professional_title = 'Robotics Engineer · Autonomous Systems · Embedded Systems', bio = 'Robotics and embedded systems engineer focused on autonomous systems. I integrate advanced sensing, SLAM, and AI to build dependable robotic systems for real-world environments.';
delete from public.experiences where role = 'ffb' and organization = 'dfb';
update public.projects set
  title = 'Offline AI Payload for Search & Rescue Robots',
  subtitle = 'A plug-in payload that lets a rescue robot find victims, talk to them and alert the team, with no internet connection.',
  summary = 'A modular payload for rescue robots that combines thermal and visual detection, a radar sensor, gas and flame sensing, an offline voice assistant and long-range alerts, all running on a small Jetson TX2 computer without internet.',
  description = $p$After an earthquake, phone networks and internet often go down, and cloud-based AI stops working exactly when it is needed. This project is a payload that works without any connection: it mounts on a ROS 2 robot, searches for victims, and keeps working when the network does not.

It combines thermal and visual detection, a radar sensor, gas and flame sensing, a voice assistant that speaks with the victim, and a long-range radio link for alerts. Everything runs on a small NVIDIA Jetson TX2 computer carried by the robot.$p$,
  status = 'Research prototype',
  tags = array['Search & Rescue','Edge AI','ROS 2','Computer Vision','Offline LLM','Sensor Fusion','LoRa','Embedded Systems'],
  tools = array['NVIDIA Jetson TX2','STM32F411 sensor hub','FLIR Lepton 3 thermal camera','YOLOv11n with TensorRT','24 GHz FMCW radar','Gemma 3 1B with llama.cpp','Whisper speech recognition','Piper text-to-speech','LoRa radio','ROS 2, Nav2 and Cartographer','TurtleBot3 Waffle Pi','TurtleBot2 Kobuki'],
  outcomes = array['Works fully offline: detection, voice dialogue and alerts need no internet','Thermal and visual detection together reduce false alarms','Victim detector reaches 96% mAP@50 at over 26 FPS on the Jetson TX2','Rescue alerts delivered over LoRa in 99% of indoor and outdoor test packets','The same payload moves between two different robot bases without modification'],
  rich_content = $p$<h2>The problem</h2><p>In the 2023 Kahramanmaraş earthquakes, cellular and internet networks failed within minutes. Most AI-assisted rescue tools depend on the cloud, so they stop working in exactly that situation. They also tend to rely on a single camera, and they rarely talk to the trapped person.</p><h2>The idea</h2><p>A self-contained payload that bolts onto a ROS 2 robot as an external &ldquo;AI brain&rdquo;. It finds people, talks to them, watches for hazards and reports back, while running entirely on the robot.</p><figure><img src="https://ntynaiuxqylscazugcdo.supabase.co/storage/v1/object/public/portfolio-media/projects/offline-ai-payload/payload-prototype.jpg" alt="The AI payload prototype with LiDAR, speaker, sensor board and camera box" /><figcaption>The payload prototype: LiDAR, speaker, sensor board and a camera box carrying the thermal and visual cameras.</figcaption></figure><h2>What it does</h2><ul><li><strong>Finds victims</strong> by combining a thermal camera, a visual detector and a radar sensor.</li><li><strong>Talks to them</strong> through an offline voice assistant that gives calm, supportive guidance until help arrives.</li><li><strong>Watches for danger</strong> with gas, flame and temperature sensors, and keeps the robot away from hazards.</li><li><strong>Reports back</strong> over Wi-Fi for maps and video, and over a long-range LoRa link when Wi-Fi drops.</li></ul><figure><img src="https://ntynaiuxqylscazugcdo.supabase.co/storage/v1/object/public/portfolio-media/projects/offline-ai-payload/architecture.png" alt="System architecture from sensors to decisions to actions" /><figcaption>System architecture: sensors feed the detector and the decision state machine, which drives navigation, the voice assistant and LoRa alerts.</figcaption></figure><h2>Seeing victims</h2><p>A low-power thermal camera watches continuously and only wakes the heavier visual detector when it sees body heat. This saves energy and cuts false alarms. The detector was trained on images we collected ourselves in the lab, showing people lying on the floor, partly hidden or in dim light, because public datasets mostly show people standing.</p><figure><img src="https://ntynaiuxqylscazugcdo.supabase.co/storage/v1/object/public/portfolio-media/projects/offline-ai-payload/training-dataset.jpg" alt="Training images of people lying in simulated disaster conditions" /><figcaption>Part of the lab-made training set: people in simulated disaster postures and lighting.</figcaption></figure><figure><img src="https://ntynaiuxqylscazugcdo.supabase.co/storage/v1/object/public/portfolio-media/projects/offline-ai-payload/detection-confirmed.jpg" alt="A person under a desk confirmed by the visual detector next to the thermal view" /><figcaption>A person partly hidden under a desk: the thermal view (right) triggers the visual detector (left), which confirms the person.</figcaption></figure><figure><img src="https://ntynaiuxqylscazugcdo.supabase.co/storage/v1/object/public/portfolio-media/projects/offline-ai-payload/no-heat-mannequin.jpg" alt="A mannequin standing in front of the robot, with no heat signature" /><figcaption>A mannequin in front of the robot: with no body heat, nothing was triggered, so no false alarm was raised.</figcaption></figure><h2>Talking to victims</h2><p>Once a victim is confirmed, the robot switches to voice mode. Speech is converted to text, a small language model prepares a short supportive reply, and a text-to-speech voice speaks it. All three steps run locally on the robot. The two heavy models cannot fit in memory together, so a small state machine switches between them quickly.</p><h2>Staying safe</h2><p>A separate microcontroller reads gas, flame and temperature sensors on a fixed schedule, so sensing is never blocked by the AI workload. When a limit is crossed, a hazard marker appears on the map and the robot plans a route around the area.</p><figure><img src="https://ntynaiuxqylscazugcdo.supabase.co/storage/v1/object/public/portfolio-media/projects/offline-ai-payload/sensor-board.jpg" alt="The sensor board with STM32 microcontroller, gas, flame and temperature sensors and LoRa radio" /><figcaption>The sensor board built around an STM32 microcontroller, with gas, flame, temperature and motion sensors and the LoRa radio.</figcaption></figure><h2>Staying connected</h2><p>Wi-Fi carries maps and video when coverage exists. A small LoRa radio carries compact status messages (robot position, victim status and hazards) when Wi-Fi is lost. Alerts and hazards show up on a command-centre screen.</p><figure><img src="https://ntynaiuxqylscazugcdo.supabase.co/storage/v1/object/public/portfolio-media/projects/offline-ai-payload/operations-map.jpg" alt="The command-centre screen showing the robot trail, a flame alert and sensor readings" /><figcaption>The command-centre dashboard in a simulation run: robot trail, a flame alert zone and sensor readings.</figcaption></figure><h2>Two different robots</h2><p>To show that the payload is not tied to one robot, it was mounted on two different bases: a TurtleBot3 Waffle Pi and a TurtleBot2 Kobuki, both working through the same ROS 2 interface.</p><figure><img src="https://ntynaiuxqylscazugcdo.supabase.co/storage/v1/object/public/portfolio-media/projects/offline-ai-payload/platform-turtlebot3.jpg" alt="The payload mounted on a TurtleBot3 Waffle Pi" /><figcaption>On a TurtleBot3 Waffle Pi, the main test platform.</figcaption></figure><figure><img src="https://ntynaiuxqylscazugcdo.supabase.co/storage/v1/object/public/portfolio-media/projects/offline-ai-payload/platform-kobuki.jpg" alt="The payload mounted on a TurtleBot2 Kobuki" /><figcaption>On a TurtleBot2 Kobuki, used to check portability.</figcaption></figure><h2>From simulation to the real robot</h2><p>Navigation and mapping were first tried in a Gazebo simulation with collapsed obstacles, narrow corridors and simulated victims, then moved to the physical robots. The robot builds a map as it moves, heads towards a confirmed victim, and avoids zones flagged as dangerous.</p><figure><img src="https://ntynaiuxqylscazugcdo.supabase.co/storage/v1/object/public/portfolio-media/projects/offline-ai-payload/simulation-rviz.jpg" alt="Gazebo simulation next to the RViz occupancy map" /><figcaption>Gazebo simulation (left) and the live occupancy map in RViz (right).</figcaption></figure><figure><img src="https://ntynaiuxqylscazugcdo.supabase.co/storage/v1/object/public/portfolio-media/projects/offline-ai-payload/operational-flow.png" alt="Operational flowchart from thermal scan to voice mode and sleep" /><figcaption>The operating loop: thermal scan, wake the detector, confirm a victim, send a LoRa alert, then switch to voice mode and back to sleep.</figcaption></figure><h2>Honest limits</h2><p>These are lab results on indoor research robots. The detector was trained on simulated disaster scenes, the radar was only tested in the lab and is meant as a confirmation sensor, and the voice assistant needs several seconds to reply. Testing in real rubble and on rugged robot bodies is the next step.</p><h2>Credits</h2><p>Built at the RAI Laboratory, Mechatronics Engineering Department, Fırat University, with Munef El Muhammed, Anas Mahyoub Naji Saeed Alqadhi and Aysegul Ucar.</p>$p$,
  updated_at = now()
where slug = 'offline-multi-sensor-ai-payload-for-usar';

insert into public.project_media (project_id, storage_path, alt, sort_order)
select p.id, v.storage_path, v.alt, v.sort_order from public.projects p cross join (values
  ('projects/offline-ai-payload/payload-prototype.jpg', 'The AI payload prototype with LiDAR, speaker, sensor board and camera box', 1),
  ('projects/offline-ai-payload/platform-turtlebot3.jpg', 'The payload mounted on a TurtleBot3 Waffle Pi', 2),
  ('projects/offline-ai-payload/platform-kobuki.jpg', 'The payload mounted on a TurtleBot2 Kobuki', 3),
  ('projects/offline-ai-payload/detection-confirmed.jpg', 'A person under a desk confirmed by the visual detector next to the thermal view', 4),
  ('projects/offline-ai-payload/simulation-rviz.jpg', 'Gazebo simulation next to the RViz occupancy map', 5)
) as v(storage_path, alt, sort_order)
where p.slug = 'offline-multi-sensor-ai-payload-for-usar' and not exists (select 1 from public.project_media m where m.project_id = p.id and m.storage_path = v.storage_path);
